"""Phase 5: `jobx bench report` on fixture CSVs generated by the fake server (tests/fixtures/bench)."""

from __future__ import annotations

import json
from pathlib import Path

import pytest
from typer.testing import CliRunner

from jobx.bench import plan
from jobx.bench.metrics import read_rows
from jobx.bench.report import build_summary, prefix_comparison, prefix_pairs, recommend, report
from jobx.cli import app

FIX = Path(__file__).resolve().parent / "fixtures" / "bench"
MATRIX = plan.load_matrix()


def _summary() -> list[dict]:
    return build_summary(FIX / "raw", FIX / "manifests", FIX / "metrics", MATRIX)


def test_summary_is_enriched_and_ordered() -> None:
    s = _summary()
    assert [x["config"] for x in s[:3]] == ["q15-bf16"] * 3  # matrix order, then concurrency
    assert [int(x["concurrency"]) for x in s[:3]] == [1, 4, 16]
    bf16 = s[0]
    assert (
        bf16["display"] == "1.5B BF16" and bf16["group"] == "quantization" and bf16["quantization"] == "none"
    )
    assert bf16["micro_f1"] == 0.90 and bf16["quality_approach"] == "vllm-qwen2.5-1.5b-bf16_few_shot"
    assert bf16["usd_per_1k_requests"] > 0 and bf16["gpu_usd_per_hour"] == plan.hourly_rate(MATRIX)["total"]
    noapc = next(x for x in s if x["config"] == "q15-bf16-noapc")
    assert noapc["enable_prefix_caching"] is False and noapc["micro_f1"] is None
    assert bf16["prefix_cache_hit_rate"] > 0 and bf16["kv_cache_usage_max"] is not None
    assert noapc["prefix_cache_hit_rate"] == 0


def test_prefix_pairs_and_comparison() -> None:
    s = _summary()
    assert sorted(prefix_pairs(s, MATRIX)) == [("q15-awq", "q15-awq-noapc"), ("q15-bf16", "q15-bf16-noapc")]
    comp = prefix_comparison(s, MATRIX)
    assert {c["concurrency"] for c in comp} == {1, 4, 16}
    low = [c for c in comp if c["concurrency"] == 1]
    assert all(c["reduction"] > 0.3 for c in low)  # fake cache factor 0.3 at concurrency 1


def test_recommender_picks_cheapest_from_measured_rows() -> None:
    s = _summary()
    recs = recommend(s, ttft_p95_s=1.0, e2e_p95_s=5.0, rps=50, workload="extract-full")
    assert recs and recs == sorted(recs, key=lambda r: (r.usd_per_hour, -r.sustainable_rps, r.config))
    top = recs[0]
    assert top.replicas >= 1 and top.usd_per_hour == pytest.approx(
        top.replicas * plan.hourly_rate(MATRIX)["total"]
    )
    assert all(r.ttft_p95_ms <= 1000 for r in recs)
    assert recommend(s, ttft_p95_s=0.001, e2e_p95_s=0.001, rps=1) == []
    assert recommend(s, ttft_p95_s=1, e2e_p95_s=5, rps=1, workload="synthetic-long") == []
    # a config whose rows all have errors is never recommended
    broken = [{**x, "error_rate": 0.5} if x["config"] == top.config else x for x in s]
    assert top.config not in {r.config for r in recommend(broken, ttft_p95_s=1, e2e_p95_s=5, rps=50)}


def test_report_writes_summary_charts_and_recommendation(tmp_path: Path) -> None:
    pytest.importorskip("matplotlib")
    res = report(
        raw_dir=FIX / "raw", manifest_dir=FIX / "manifests", metrics_dir=FIX / "metrics", out_dir=tmp_path
    )
    rows = read_rows([res["summary"]])
    assert len(rows) == 12 and {r["config"] for r in rows} == {
        "q15-bf16",
        "q15-awq",
        "q15-bf16-noapc",
        "q15-awq-noapc",
    }
    names = {p.name for p in res["charts"]}
    assert names == {
        "latency_throughput_extract-full.png",
        "cost_per_1k_extract-full.png",
        "prefix_caching_ttft.png",
        "quality_vs_throughput.png",
    }
    assert all(p.stat().st_size > 5000 for p in res["charts"])
    rec = json.loads(res["recommendation"].read_text())
    assert rec["target"]["rps"] == 10 and rec["recommended"]["config"] in {r["config"] for r in rows}
    assert rec["prefix_caching"]
    empty = report(
        raw_dir=tmp_path / "none", manifest_dir=tmp_path, metrics_dir=tmp_path, out_dir=tmp_path / "x"
    )
    assert empty["summary"] is None


def test_report_and_recommend_cli(tmp_path: Path) -> None:
    runner = CliRunner()
    res = runner.invoke(
        app,
        ["bench", "report", "--raw-dir", str(FIX / "raw"), "--manifest-dir", str(FIX / "manifests"),
         "--metrics-dir", str(FIX / "metrics"), "--out-dir", str(tmp_path), "--no-charts"],
    )  # fmt: skip
    assert res.exit_code == 0, res.output
    res = runner.invoke(
        app, ["bench", "recommend", "--summary", str(tmp_path / "summary.csv"), "--rps", "20"]
    )
    assert res.exit_code == 0 and "recommended:" in res.output
    res = runner.invoke(
        app, ["bench", "recommend", "--summary", str(tmp_path / "summary.csv"), "--ttft-p95", "0.0001"]
    )
    assert res.exit_code == 1 and "no measured config" in res.output
    res = runner.invoke(
        app, ["bench", "report", "--raw-dir", str(tmp_path / "nothing"), "--out-dir", str(tmp_path / "o")]
    )
    assert res.exit_code == 0 and "nothing to report" in res.output
